'use strict';
const ZEN_TERMS=Object.freeze({Idea:'Ý tưởng',List:'Việc cần làm',Doing:'Đang thực hiện',Done:'Hoàn thành',Settings:'Cài đặt',Timeline:'Dòng thời gian',Calendar:'Lịch',Kanban:'Bảng Kanban'});
function zenTerm(code){return ZEN_TERMS[code]||code;}
columnDisplayName=function(p,key){const custom=p?.columnNames?.[key];return custom&&custom!==key?custom:zenTerm(key);};
const zenListBaseTable=table;
table=function(tasks){const sorted=tasks.slice().sort((a,b)=>(workDeadline(a)||'9999').localeCompare(workDeadline(b)||'9999')||a.title.localeCompare(b.title,'vi'));const template=document.createElement('template');template.innerHTML=zenListBaseTable(sorted);const head=template.content.querySelector('thead tr');head?.insertAdjacentHTML('beforeend','<th>HẠN CHÓT</th><th>ƯU TIÊN</th>');for(const row of template.content.querySelectorAll('tbody tr[data-task]')){const p=project(row.dataset.pid),t=p?.tasks.find(x=>x.id===row.dataset.task);if(!t)continue;const status=row.querySelector('.status');if(status)status.textContent=columnDisplayName(p,t.col);const due=workDeadline(t),late=due&&due<today()&&t.col!=='Done';row.classList.toggle('zen-row-overdue',!!late);row.insertAdjacentHTML('beforeend','<td data-label="Hạn chót" class="zen-quick-due"><label><span class="zen-due-label">'+(late?'Quá hạn · ':'')+esc(due?dateLabel(due):'Chưa đặt hạn')+'</span><input type="date" aria-label="Hạn chót: '+esc(t.title)+'" data-zen-quick-due readonly aria-haspopup="dialog" value="'+esc(due)+'"></label></td><td data-label="Ưu tiên" class="zen-quick-priority-cell"><select aria-label="Ưu tiên: '+esc(t.title)+'" data-zen-quick-priority>'+priorityOptions(t.priority||'')+'</select></td>');}for(const select of template.content.querySelectorAll('[data-zen-quick-priority]')){const options=[...select.options],picker=document.createElement('details');picker.className='zen-priority-picker';picker.dataset.zenPriorityPicker='';picker.innerHTML='<summary aria-label="'+esc(select.getAttribute('aria-label'))+'" aria-haspopup="listbox"><span class="zen-priority-current"></span><span class="zen-priority-chevron" aria-hidden="true"></span></summary><div class="zen-priority-menu" role="listbox" aria-label="'+esc(select.getAttribute('aria-label'))+'"></div>';const summary=picker.querySelector('summary'),list=picker.querySelector('[role=listbox]');for(const option of options){const item=document.createElement('button');item.type='button';item.dataset.zenPriorityOption=option.value;item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.textContent=option.textContent;list.append(item);if(option.selected)picker.querySelector('.zen-priority-current').textContent=option.textContent;}select.tabIndex=-1;select.setAttribute('aria-hidden','true');select.closest('td').append(picker);select.before(picker);}template.content.querySelector('td[colspan]')?.setAttribute('colspan','6');return template.innerHTML;};
document.addEventListener('click',e=>{const dueInput=e.target.closest('[data-zen-quick-due]')||e.target.closest('.zen-quick-due label')?.querySelector('[data-zen-quick-due]');if(dueInput){e.preventDefault();zenOpenDatePicker(dueInput);e.stopImmediatePropagation();return;}const picker=e.target.closest('[data-zen-priority-picker]');if(picker){e.stopImmediatePropagation();const choice=e.target.closest('[data-zen-priority-option]');if(choice){const select=picker.parentElement.querySelector('[data-zen-quick-priority]');if(!select)return;select.value=choice.dataset.zenPriorityOption;picker.querySelector('.zen-priority-current').textContent=choice.textContent;picker.querySelectorAll('[role=option]').forEach(option=>option.setAttribute('aria-selected',String(option===choice)));picker.open=false;select.dispatchEvent(new Event('change',{bubbles:true}));}return;}if(e.target.closest('[data-zen-quick-priority]'))e.stopImmediatePropagation();const due=e.target.closest('[data-open-due]');if(due){e.preventDefault();e.stopImmediatePropagation();dashboardDueFilter='overdue';filterStatus='';filterProject='';filterPriority='';go('tasks');}},true);
document.addEventListener('change',e=>{const input=e.target;if(!input.matches('[data-zen-quick-due],[data-zen-quick-priority]'))return;const row=input.closest('tr'),p=project(row.dataset.pid),t=p?.tasks.find(x=>x.id===row.dataset.task);if(!t)return;const before=structuredClone(t);if(input.hasAttribute('data-zen-quick-priority'))t.priority=input.value;else{const day=input.value;if(day&&t.start&&day<t.start.slice(0,10)){input.value=workDeadline(t);notify('Hạn chót phải từ ngày bắt đầu trở đi.');return;}t.due=day;t.end=day?day+(t.end?.slice(10)||'T17:00'):'';}if(save()===false){Object.assign(t,before);notify('Chưa lưu được thay đổi.');}render();},true);
const zenListTimeline=timelineTask;timelineTask=function(t){const html=zenListTimeline(t),template=document.createElement('template');template.innerHTML=html;const small=template.content.querySelector('small');if(small)small.textContent=small.textContent.replace(' · '+t.col+' · ',' · '+columnDisplayName(t.project,t.col)+' · ');return template.innerHTML;};
const zenListAlerts=refreshDueAlerts;refreshDueAlerts=function(){if(!['dashboard','tasks'].includes(view)){document.querySelector('#due-alert-strip')?.remove();return;}zenListAlerts();};
function zenTranslateLabels(root){if(!root)return;for(const option of root.querySelectorAll('option'))if(!option.hasAttribute('value'))option.value=option.textContent;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const changes=[];while(walker.nextNode()){const node=walker.currentNode;if(node.parentElement.closest('script,style,textarea,input,.task-name,.task-card h3,.zen-formatted,.wf-card-description,.wf-task-description'))continue;const text=node.nodeValue.trim();if(ZEN_TERMS[text])changes.push([node,node.nodeValue.replace(text,zenTerm(text))]);}for(const [node,value]of changes)node.nodeValue=value;for(const option of root.querySelectorAll('#filter-status option,.wf-bulk-state option')){if(!option.hasAttribute('value'))option.value=option.textContent;option.textContent=zenTerm(option.value)||option.textContent;}}
const zenListRender=render;render=function(){zenListRender();zenTranslateLabels(document.querySelector('.sidebar'));zenTranslateLabels(document.querySelector('.topbar'));zenTranslateLabels(document.querySelector('#main'));const sort=document.querySelector('.wf-sort');if(view==='tasks'&&sort&&(!_WF.listSort||_WF.listSort==='default')){sort.value='due';sort.onchange({target:sort});}};
const zenListAccount=accountPanel;accountPanel=function(){zenListAccount();zenTranslateLabels(document.querySelector('#editor-body'));};

/* A compact, localized date picker for quick task deadlines. */
let zenDatePickerState=null;
const zenDateToday=()=>new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Ho_Chi_Minh'}));
const zenDateIso=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
function zenCloseDatePicker(restore=false){const state=zenDatePickerState;if(!state)return;state.node.remove();zenDatePickerState=null;if(restore&&state.input.isConnected)state.input.focus({preventScroll:true});}
function zenPaintDatePicker(){const state=zenDatePickerState;if(!state)return;const {input,node,month}=state;const year=month.getFullYear(),monthIndex=month.getMonth(),first=new Date(year,monthIndex,1),offset=(first.getDay()+6)%7,days=new Date(year,monthIndex+1,0).getDate(),selected=input.value;const title=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(first);node.innerHTML='<header class="zen-date-head"><button type="button" data-date-prev aria-label="Tháng trước">‹</button><strong>'+title+'</strong><button type="button" data-date-next aria-label="Tháng sau">›</button></header><div class="zen-date-week" aria-hidden="true">'+['T2','T3','T4','T5','T6','T7','CN'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="zen-date-days" role="grid" aria-label="'+title+'">'+Array.from({length:offset},()=>'<span class="is-empty"></span>').join('')+Array.from({length:days},(_,i)=>{const d=new Date(year,monthIndex,i+1),iso=zenDateIso(d),today=iso===zenDateIso(zenDateToday());return '<button type="button" role="gridcell" data-date-value="'+iso+'" aria-pressed="'+(iso===selected)+'" class="'+(today?'is-today ':'')+(iso===selected?'is-selected':'')+'">'+(i+1)+'</button>';}).join('')+'</div><footer><button type="button" data-date-clear>Xóa hạn</button><button type="button" data-date-today>Hôm nay</button></footer>';}
function zenOpenDatePicker(input){zenCloseDatePicker();input.readOnly=true;input.setAttribute('aria-haspopup','dialog');const node=document.createElement('section');node.className='zen-date-popover';node.setAttribute('role','dialog');node.setAttribute('aria-label','Chọn hạn chót');document.body.append(node);let month=input.value?new Date(input.value+'T12:00:00'):zenDateToday();if(Number.isNaN(month.getTime()))month=zenDateToday();month=new Date(month.getFullYear(),month.getMonth(),1);zenDatePickerState={input,node,month};zenPaintDatePicker();const rect=input.getBoundingClientRect(),width=Math.min(280,window.innerWidth-24),height=330;let left=Math.min(Math.max(12,rect.right-width),window.innerWidth-width-12),top=rect.bottom+8;if(top+height>window.innerHeight-10)top=Math.max(10,rect.top-height-8);node.style.left=left+'px';node.style.top=top+'px';node.querySelector('[data-date-value="'+(input.value||'')+'"]')?.focus({preventScroll:true});}
document.addEventListener('click',e=>{const state=zenDatePickerState;if(!state)return;if(e.target.closest('.zen-date-popover')){const button=e.target.closest('button');if(!button)return;e.preventDefault();e.stopPropagation();if(button.hasAttribute('data-date-prev'))state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);else if(button.hasAttribute('data-date-next'))state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);else if(button.hasAttribute('data-date-value')){state.input.value=button.dataset.dateValue;state.input.dispatchEvent(new Event('change',{bubbles:true}));zenCloseDatePicker(true);return;}else if(button.hasAttribute('data-date-today')){state.input.value=zenDateIso(zenDateToday());state.input.dispatchEvent(new Event('change',{bubbles:true}));zenCloseDatePicker(true);return;}else if(button.hasAttribute('data-date-clear')){state.input.value='';state.input.dispatchEvent(new Event('change',{bubbles:true}));zenCloseDatePicker(true);return;}zenPaintDatePicker();return;}zenCloseDatePicker();},true);
document.addEventListener('keydown',e=>{if(!zenDatePickerState)return;if(e.key==='Escape'){e.preventDefault();zenCloseDatePicker(true);}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const day=e.target.closest('[data-date-value]');if(day){const all=[...zenDatePickerState.node.querySelectorAll('[data-date-value]')],i=all.indexOf(day),next=all[i+(e.key==='ArrowRight'?1:-1)];if(next){e.preventDefault();next.focus();}}}},true);

document.addEventListener('click',e=>{if(e.target.closest('[data-zen-priority-picker]'))return;document.querySelectorAll('[data-zen-priority-picker][open]').forEach(p=>p.open=false);},true);
document.addEventListener('keydown',e=>{const picker=e.target.closest('[data-zen-priority-picker]');if(!picker)return;if(e.key==='Escape'&&picker.open){picker.open=false;picker.querySelector('summary')?.focus();return;}if(e.key==='ArrowDown'&&e.target.matches('[role=option]')){e.preventDefault();(e.target.nextElementSibling||picker.querySelector('[role=option]'))?.focus();}if(e.key==='ArrowUp'&&e.target.matches('[role=option]')){e.preventDefault();(e.target.previousElementSibling||picker.querySelector('[role=option]:last-child'))?.focus();}});

document.addEventListener('toggle',e=>{const picker=e.target;if(!(picker instanceof HTMLDetailsElement)||!picker.matches('[data-zen-priority-picker]'))return;const menu=picker.querySelector('.zen-priority-menu');if(!menu)return;if(!picker.open){menu.style.position='';menu.style.left='';menu.style.right='';menu.style.top='';menu.style.width='';return;}const rect=picker.querySelector('summary').getBoundingClientRect(),width=Math.min(Math.max(rect.width,210),window.innerWidth-24),height=Math.min(280,window.innerHeight*.45),left=Math.max(12,Math.min(rect.right-width,window.innerWidth-width-12));let top=rect.bottom+6;if(top+height>window.innerHeight-10)top=Math.max(10,rect.top-height-6);menu.style.position='fixed';menu.style.left=left+'px';menu.style.right='auto';menu.style.top=top+'px';menu.style.width=width+'px';},true);
